19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Assigns, on create, the owner's numeric membership level.
24	 * <p>
25	 * The level starts at {@link #BASE_LEVEL}, gains a point when the owner has an email
26	 * address, another when the owner has no namesakes ({@code namesakeCount} is 0), and a
27	 * final one for tenured members, up to {@link #MAX_LEVEL}. The top level requires tenure of
28	 * more than {@link #LEVEL_4_MIN_TENURE_DAYS} days; a newly created owner has not yet accrued
29	 * any tenure, so on create the level earned can never exceed 3. As it reads the owner's
30	 * namesake count, this must be assigned after {@link NamesakeCounter} and before the owner
31	 * is saved.
32	 */
33	@Component
34	public class MembershipLevelAssigner {
35	
36	    /** The level every owner starts at. */
37	    static final int BASE_LEVEL = 1;
38	
39	    /** The highest membership level an owner can hold; only reachable through tenure. */
40	    static final int MAX_LEVEL = 4;
41	
42	    /** Tenure, in days, an owner must exceed to reach the top {@link #MAX_LEVEL top level}. */
43	    static final int LEVEL_4_MIN_TENURE_DAYS = 365;
44	
45	    /**
46	     * Assigns {@code owner}'s membership level from its own fields and tenure. Call this after
47	     * the namesake count has been assigned and before the owner is saved.
48	     *
49	     * @param owner the owner being created
50	     */
51	    public void assign(Owner owner) {
52	        int level = BASE_LEVEL;
53	        if (hasEmail(owner)) {
54	            level++;
55	        }
56	        if (hasNoNamesakes(owner)) {
57	            level++;
58	        }
59	        if (hasQualifyingTenure(owner)) {
60	            level++;
61	        }
62	        owner.setMembershipLevel(Math.min(level, MAX_LEVEL));
63	    }
64	
65	    private boolean hasEmail(Owner owner) {
66	        return owner.getEmail() != null && !owner.getEmail().isBlank();
67	    }
68	
69	    private boolean hasNoNamesakes(Owner owner) {
70	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
71	    }
72	
73	    /**
74	     * Whether the owner's tenure exceeds the {@link #LEVEL_4_MIN_TENURE_DAYS} that the top
75	     * level requires. A newly created owner has not yet accrued any tenure, so on create this
76	     * is always {@code false} and a new owner never exceeds level 3.
77	     */
78	    private boolean hasQualifyingTenure(Owner owner) {
79	        return tenureDays(owner) > LEVEL_4_MIN_TENURE_DAYS;
80	    }
81	
82	    /** The whole days the owner has been a member; zero for an owner being created. */
83	    private long tenureDays(Owner owner) {
84	        return 0L;
85	    }
86	}
