16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "membership_level")
76	    private Integer membershipLevel;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "possible_duplicate")
82	    private Boolean possibleDuplicate;
83	
84	    @Column(name = "possible_duplicate_of")
85	    private Integer possibleDuplicateOf;
86	
87	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
88	    private Set<Pet> pets;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getTelephone() {
107	        return this.telephone;
108	    }
109	
110	    public void setTelephone(String telephone) {
111	        this.telephone = telephone;
112	    }
113	
114	    /**
115	     * The owner's stored E.164 {@link #telephone} formatted for humans: the country code, a
116	     * space, then the national digits grouped in threes, e.g. {@code "+61 412 345 678"}.
117	     * Derived on read; {@code null} until a telephone has been set.
118	     */
119	    @Transient
120	    public String getTelephoneDisplay() {
121	        return TelephoneDisplay.format(this.telephone);
122	    }
123	
124	    public String getEmail() {
125	        return this.email;
126	    }
127	
128	    public void setEmail(String email) {
129	        this.email = email;
130	    }
131	
132	    public String getPostcode() {
133	        return this.postcode;
134	    }
135	
136	    public void setPostcode(String postcode) {
137	        this.postcode = postcode;
138	    }
139	
140	    public LocalDate getRegistrationDate() {
141	        return this.registrationDate;
142	    }
143	
144	    public void setRegistrationDate(LocalDate registrationDate) {
145	        this.registrationDate = registrationDate;
146	    }
147	
148	    public LocalDate getBirthDate() {
149	        return this.birthDate;
150	    }
151	
152	    public void setBirthDate(LocalDate birthDate) {
153	        this.birthDate = birthDate;
154	    }
155	
156	    /**
157	     * The owner's {@link AgeBand age band} as of their {@link #registrationDate}, derived on
158	     * read from the owner's {@link #birthDate}. {@code null} until both the birth date and the
159	     * registration date have been supplied.
160	     */
161	    @Transient
162	    public String getAgeBand() {
163	        if (this.birthDate == null || this.registrationDate == null) {
164	            return null;
165	        }
166	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
167	    }
168	
169	    public String getCustomerCode() {
170	        return this.customerCode;
171	    }
172	
173	    public void setCustomerCode(String customerCode) {
174	        this.customerCode = customerCode;
175	    }
176	
177	    /**
178	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
179	     * {@code YY} is the last two digits of the {@code registrationDate} year, e.g.
180	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
181	     * both the customer code and registration date have been assigned.
182	     */
183	    @Transient
184	    public String getMembershipNumber() {
185	        if (this.customerCode == null || this.registrationDate == null) {
186	            return null;
187	        }
188	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
189	    }
190	
191	    /**
192	     * The owner's check digit: a single {@link Luhn} check digit computed over the digits
193	     * of the owner's {@link #customerCode}. {@code null} until the customer code has been
194	     * assigned.
195	     */
196	    @Transient
197	    public Integer getCheckDigit() {
198	        if (this.customerCode == null) {
199	            return null;
200	        }
201	        return Luhn.checkDigit(this.customerCode);
202	    }
203	
204	    /**
205	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
206	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
207	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
208	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
209	     * segment of the owner's {@link #getCustomerCode() customer code}.
210	     */
211	    @Transient
212	    public String getRegion() {
213	        return RegionPostcodeTable.regionOf(this.postcode)
214	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
215	    }
216	
217	    /**
218	     * The owner's locality, read from its region-and-hash identity: the {@code REGION}
219	     * segment (everything before the first {@code '-'}) of the owner's
220	     * {@link #getCustomerCode() customer code}. Falls back to the owner's live
221	     * {@link #getRegion() region} until a customer code has been assigned.
222	     */
223	    @Transient
224	    public String getLocality() {
225	        if (this.customerCode == null) {
226	            return getRegion();
227	        }
228	        int dash = this.customerCode.indexOf('-');
229	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
230	    }
231	
232	    /**
233	     * The owner's preferred contact channel, derived on read from the owner's own
234	     * fields: {@code "EMAIL"} when the owner has an email address, otherwise
235	     * {@code "PHONE"}.
236	     */
237	    @Transient
238	    public String getContactPreference() {
239	        return (this.email == null || this.email.isBlank()) ? "PHONE" : "EMAIL";
240	    }
241	
242	    /**
243	     * The owner's identity key: the single value used to detect duplicate owners on
244	     * create. It joins the owner's (already normalized) telephone, email and household id
245	     * with {@code '|'} — {@code <telephone>|<email>|<householdId>} — a missing email or
246	     * household id contributing an empty segment. Two owners are duplicates only when
247	     * their whole identity keys are equal.
248	     */
249	    @Transient
250	    public String getIdentityKey() {
251	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
252	    }
253	
254	    private static String orEmpty(String value) {
255	        return value == null ? "" : value;
256	    }
257	
258	    public String getHouseholdId() {
259	        return this.householdId;
260	    }
261	
262	    public void setHouseholdId(String householdId) {
263	        this.householdId = householdId;
264	    }
265	
266	    public Integer getNamesakeCount() {
267	        return this.namesakeCount;
268	    }
269	
270	    public void setNamesakeCount(Integer namesakeCount) {
271	        this.namesakeCount = namesakeCount;
272	    }
273	
274	    public Integer getHouseholdSize() {
275	        return this.householdSize;
276	    }
277	
278	    public void setHouseholdSize(Integer householdSize) {
279	        this.householdSize = householdSize;
280	    }
281	
282	    /**
283	     * The owner's membership level, a number assigned on create and never below 1.
284	     * Levels 1 to 3 are earned from the owner's own fields at creation time (see
285	     * {@code MembershipLevelAssigner}); level 4 is reserved for tenure.
286	     */
287	    public Integer getMembershipLevel() {
288	        return this.membershipLevel;
289	    }
290	
291	    public void setMembershipLevel(Integer membershipLevel) {
292	        this.membershipLevel = membershipLevel;
293	    }
294	
295	    public Boolean getBulkSignupWarning() {
296	        return this.bulkSignupWarning;
297	    }
298	
299	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
300	        this.bulkSignupWarning = bulkSignupWarning;
301	    }
302	
303	    /**
304	     * Whether this owner, when created, softly matched an already-stored owner: one that
305	     * shares its last name and postcode but carries a different telephone. Assigned on
306	     * create; when {@code true}, {@link #getPossibleDuplicateOf()} identifies the matched
307	     * owner.
308	     */
309	    public Boolean getPossibleDuplicate() {
310	        return this.possibleDuplicate;
311	    }
312	
313	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
314	        this.possibleDuplicate = possibleDuplicate;
315	    }
316	
317	    /**
318	     * The id of the already-stored owner this owner softly matched on create (same last
319	     * name and postcode, different telephone), or {@code null} when it matched none.
320	     */
321	    public Integer getPossibleDuplicateOf() {
322	        return this.possibleDuplicateOf;
323	    }
324	
325	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
326	        this.possibleDuplicateOf = possibleDuplicateOf;
327	    }
328	
329	    protected Set<Pet> getPetsInternal() {
330	        if (this.pets == null) {
331	            this.pets = new HashSet<>();
332	        }
333	        return this.pets;
334	    }
335	
336	    protected void setPetsInternal(Set<Pet> pets) {
337	        this.pets = pets;
338	    }
339	
340	    public List<Pet> getPets() {
341	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
342	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
343	        return Collections.unmodifiableList(sortedPets);
344	    }
345	
346	    public void setPets(List<Pet> pets) {
347	        this.pets = new HashSet<>(pets);
348	    }
349	
350	    public void addPet(Pet pet) {
351	        getPetsInternal().add(pet);
352	        pet.setOwner(this);
353	    }
354	
355	    /**
356	     * Return the Pet with the given name, or null if none found for this Owner.
357	     *
358	     * @param name to test
359	     * @return true if pet name is already in use
360	     */
361	    public Pet getPet(String name) {
362	        return getPet(name, false);
363	    }
364	
365	    /**
366	     * Return the Pet with the given name, or null if none found for this Owner.
367	     *
368	     * @param name to test
369	     * @return true if pet name is already in use
370	     */
371	    public Pet getPet(String name, boolean ignoreNew) {
372	        name = name.toLowerCase();
373	        for (Pet pet : getPetsInternal()) {
374	            if (!ignoreNew || !pet.isNew()) {
375	                String compName = pet.getName();
376	                compName = compName.toLowerCase();
377	                if (compName.equals(name)) {
378	                    return pet;
379	                }
380	            }
381	        }
382	        return null;
383	    }
384	
385	    public Pet getPet(Integer petId) {
386	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
387	    }
388	
389	    @Override
390	    public String toString() {
391	        return new ToStringCreator(this)
392	
393	            .append("id", this.getId())
394	            .append("new", this.isNew())
395	            .append("lastName", this.getLastName())
396	            .append("firstName", this.getFirstName())
397	            .append("address", this.address)
398	            .append("city", this.city)
399	            .append("telephone", this.telephone)
400	            .append("email", this.email)
401	            .append("registrationDate", this.registrationDate)
402	            .append("customerCode", this.customerCode)
403	            .toString();
404	    }
405	}
